import { useState, useEffect } from 'react';
import { updatePOOperationStatus } from '../../services/purchaseOrderService';
import { useNotification } from './NotificationSystem';
import { FiCheck, FiClock, FiAlertCircle, FiX, FiInfo, FiEdit, FiSave, FiXCircle } from 'react-icons/fi';

const STATUS_CONFIG = {
  pending: {
    label: 'Pending',
    icon: <FiClock className="mr-1.5" />,
    color: 'bg-yellow-100 text-yellow-800',
    nextStatus: 'in_progress',
    nextLabel: 'Start Work',
    nextColor: 'bg-blue-100 text-blue-800 hover:bg-blue-200',
  },
  in_progress: {
    label: 'In Progress',
    icon: <FiInfo className="mr-1.5" />,
    color: 'bg-blue-100 text-blue-800',
    nextStatus: 'completed',
    nextLabel: 'Mark as Completed',
    nextColor: 'bg-green-100 text-green-800 hover:bg-green-200',
  },
  completed: {
    label: 'Completed',
    icon: <FiCheck className="mr-1.5" />,
    color: 'bg-green-100 text-green-800',
    nextStatus: null,
  },
  blocked: {
    label: 'Blocked',
    icon: <FiAlertCircle className="mr-1.5" />,
    color: 'bg-red-100 text-red-800',
    nextStatus: 'in_progress',
    nextLabel: 'Resume Work',
    nextColor: 'bg-blue-100 text-blue-800 hover:bg-blue-200',
  },
  cancelled: {
    label: 'Cancelled',
    icon: <FiX className="mr-1.5" />,
    color: 'bg-gray-100 text-gray-800',
    nextStatus: null,
  },
};

export default function POStatusManager({ poId, currentStatus = 'pending', onStatusUpdate, operations = [], operationsStatus = {} }) {
  const [isEditing, setIsEditing] = useState(false);
  const [selectedStatus, setSelectedStatus] = useState(currentStatus);
  const [notes, setNotes] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const { showSuccess, showError } = useNotification();

  useEffect(() => {
    setSelectedStatus(currentStatus);
  }, [currentStatus]);

  const handleStatusChange = (e) => {
    setSelectedStatus(e.target.value);
  };

  const handleUpdateStatus = async (e) => {
    e && e.preventDefault();
    if (!selectedStatus || selectedStatus === currentStatus) {
      setIsEditing(false);
      return;
    }

    try {
      setIsUpdating(true);
      // Update the main PO status
      if (onStatusUpdate) {
        await onStatusUpdate(selectedStatus, notes);
      }
      
      // If there are operations, update their statuses as well
      if (operations.length > 0) {
        const updates = operations.map(op => 
          updatePOOperationStatus(poId, op, 0, selectedStatus, { uid: 'system' }, notes)
        );
        await Promise.all(updates);
      }
      
      showSuccess(`Status updated to ${STATUS_CONFIG[selectedStatus]?.label || selectedStatus}`);
      setIsEditing(false);
      setNotes('');
    } catch (error) {
      console.error('Error updating status:', error);
      showError('Failed to update status');
    } finally {
      setIsUpdating(false);
    }
  };

  const handleQuickAction = (newStatus) => {
    setSelectedStatus(newStatus);
    handleUpdateStatus();
  };

  const currentConfig = STATUS_CONFIG[currentStatus] || {};
  const nextStatus = currentConfig.nextStatus;
  const nextConfig = nextStatus ? STATUS_CONFIG[nextStatus] : null;

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200">
        <h3 className="text-sm font-medium text-gray-700 mb-2">Update Status</h3>
        <form onSubmit={handleUpdateStatus} className="space-y-3">
          <select
            value={selectedStatus}
            onChange={handleStatusChange}
            className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
            disabled={isUpdating}
          >
            {Object.entries(STATUS_CONFIG).map(([value, config]) => (
              <option key={value} value={value}>
                {config.label}
              </option>
            ))}
          </select>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              rows="2"
              placeholder="Add any notes about this status change..."
            />
          </div>
          
          <div className="flex justify-end space-x-2">
            <button
              type="button"
              onClick={() => {
                setIsEditing(false);
                setSelectedStatus(currentStatus);
                setNotes('');
              }}
              className="px-3 py-1.5 text-sm text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"
              disabled={isUpdating}
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-3 py-1.5 text-sm text-white bg-indigo-600 rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
              disabled={isUpdating}
            >
              {isUpdating ? 'Updating...' : 'Update Status'}
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Current Status */}
      <div className="flex items-center justify-between">
        <div className="flex items-center">
          <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${currentConfig.color}`}>
            {currentConfig.icon}
            {currentConfig.label}
          </span>
        </div>
        <button
          type="button"
          onClick={() => setIsEditing(true)}
          className="inline-flex items-center px-2.5 py-1.5 border border-transparent text-xs font-medium rounded text-indigo-700 bg-indigo-100 hover:bg-indigo-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          <FiEdit className="mr-1 h-3 w-3" />
          Change
        </button>
      </div>

      {/* Quick Actions */}
      {nextStatus && (
        <div className="space-y-2">
          <button
            type="button"
            onClick={() => handleQuickAction(nextStatus)}
            className={`w-full flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-md ${nextConfig.nextColor} focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500`}
            disabled={isUpdating}
          >
            {isUpdating ? 'Updating...' : nextConfig.nextLabel}
          </button>
          
          {currentStatus === 'in_progress' && (
            <button
              type="button"
              onClick={() => handleQuickAction('blocked')}
              className="w-full flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-md bg-yellow-100 text-yellow-800 hover:bg-yellow-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-yellow-500"
              disabled={isUpdating}
            >
              <FiAlertCircle className="mr-2 h-4 w-4" />
              Mark as Blocked
            </button>
          )}
        </div>
      )}

      {/* Operation Statuses */}
      {operations.length > 0 && (
        <div className="mt-4">
          <h4 className="text-sm font-medium text-gray-700 mb-2">Operation Status</h4>
          <div className="space-y-2">
            {operations.map((op) => {
              const opStatus = operationsStatus[op]?.status || 'pending';
              const opConfig = STATUS_CONFIG[opStatus] || STATUS_CONFIG.pending;
              return (
                <div key={op} className="flex items-center justify-between">
                  <span className="text-sm text-gray-600">{op}</span>
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${opConfig.color}`}>
                    {opConfig.icon}
                    {opConfig.label}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
